function sceneView(which){if(which!=='mall')document.querySelector('#mall-panel')?.classList.add('hidden');if(window.CrowSpaces?.openScene(which))return;scene=which;state.scene=which;save();cv.width=which==='town'?1400:1500;cv.height=850;ctx.imageSmoothingEnabled=false;$('#scene-title').textContent=which==='town'?'Around the neighbourhood':'Inside Crow HQ';$('#town-tab').classList.toggle('active',which==='town');$('#indoor-tab').classList.toggle('active',which==='inside');$('#world-caption').textContent=which==='town'?'KUALA LUMPUR, REIMAGINED IN PIXELS':'CROW HQ · THE WORKING FLOOR';$('#destination-bar').classList.toggle('hidden',which!=='town');$('.office-stage').classList.toggle('town-scene',which==='town');$('#exit-hq').textContent=window.CrowCommunity?.isJoined()?(which==='town'?'Find my character ↗':'Exit HQ ↗'):which==='town'?'Explore the neighbourhood ↗':'Exit HQ ↗';cv.setAttribute('aria-label',which==='town'?'Pixel Malaysian neighbourhood with golden Crow HQ twin towers, Mamak Corner, 7-Eleven, Kedai Kopi Pagi, and a park. Use destination buttons below to visit.':'Animated Crow HQ office. Use teammate cards to select a character.');}
function setupTown(){sceneView(state.scene==='inside'?'inside':'town');$('#town-tab').onclick=()=>sceneView('town');$('#indoor-tab').onclick=()=>window.CrowCommunity?.isJoined()?window.CrowCommunity.go('hq'):sceneView('inside');$('#exit-hq').onclick=()=>{if(window.CrowCommunity?.isJoined()){if(scene==='town')window.CrowCommunity.focus();else window.CrowCommunity.go(['suite','mall'].includes(scene)?'hq':'work');return;}if(window.CrowAccess?.role==='founder'){window.CrowCommunity?.focus();return;}setMode('bobby','plaza');sceneView('town');toast('Bobby is heading out through the HQ lobby.');};$('#destination-bar').innerHTML=Object.entries(places).map(([id,p])=>`<button class="destination" data-place="${id}" style="--place-color:${p.color}"><span class="destination-icon">${id==='hq'?'▥':id==='mamak'?'♨':id==='seven'?'7':id==='kopi'?'☕':'♧'}</span><span><strong>${p.name}</strong><small>${p.type}</small></span><span class="destination-arrow">↗</span></button>`).join('');$$('[data-place]').forEach(b=>b.onclick=()=>openPlace(b.dataset.place));}
function openPlace(id){const p=places[id];if(!p)return;const guests=actors.filter(a=>a.zone==='town'&&a.destination===id);$('#place-content').innerHTML=`<div class="dialog-heading"><div><span class="eyebrow">${p.tag}</span><h2>${p.name}</h2></div><button class="icon-btn" data-close aria-label="Close destination">×</button></div><div class="place-illustration" style="background:${p.accent}"><canvas id="food-art" width="460" height="124" aria-label="${id==='hq'?'Golden twin towers':id==='mamak'?'Roti canai, curry and teh tarik':id==='kopi'?'Kopi, kaya toast and eggs':id==='seven'?'A drink and an ice cream':'A leafy park'} pixel illustration"></canvas><span>${p.type}</span></div><p class="place-description">${p.description}</p><div class="place-menu">${p.menu.map(([name,desc],i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><div><strong>${name}</strong><p>${desc}</p></div></div>`).join('')}</div><button class="primary space-enter" id="space-enter">${id==='hq'?'Join the Crow HQ floor':id==='plaza'?'Visit the park':'Enter & take a seat'} ↗</button><div class="visit-form founder-only"><label for="visit-person">${id==='hq'?'Who is heading back?':'Who’s taking a break?'}</label><select id="visit-person">${people.map(q=>`<option value="${q.id}" ${q.id==='bobby'?'selected':''}>${q.name} · ${q.role}</option>`).join('')}</select><button id="visit-go" class="primary">${id==='hq'?'Enter Crow HQ':id==='plaza'?'Take a little walk':'Lepak here'} ↗</button></div><p class="form-note">${guests.length?guests.map(a=>person(a.id).name).join(', ')+' heading here or already enjoying a break. ':''}A fictional pixel neighbourhood. Visits are animated; no food orders or purchases are made.</p>`;$('#place-dialog').showModal();drawFoodArt(id);$('#space-enter').onclick=()=>{$('#place-dialog').close();window.CrowCommunity?.go(id==='hq'?'hq':id==='plaza'?'park':id);};$('#visit-go').onclick=()=>{const who=$('#visit-person').value;setMode(who,id==='hq'?'work':id);$('#place-dialog').close();sceneView(id==='hq'?'inside':'town');toast(`${person(who).name} is ${id==='hq'?'heading back to HQ':'heading to '+p.name}.`);};}
